import sys

def is_valid_word(s):
    if not s or len(s) > 16:
        return False
    for c in s:
        if not (c.isalnum() or c == '_'):
            return False
    return True

def is_valid_hostname(hostname):
    if not hostname or len(hostname) > 32:
        return False
    parts = hostname.split('.')
    if not parts:
        return False
    for part in parts:
        if not is_valid_word(part):
            return False
    return True

def is_valid_jabber_id(s):
    if '@' not in s:
        return False

    at_index = s.index('@')
    username = s[:at_index]
    rest = s[at_index + 1:]

    if not is_valid_word(username):
        return False

    slash_index = rest.find('/')
    if slash_index == -1:
        hostname = rest
        resource = None
    else:
        hostname = rest[:slash_index]
        resource = rest[slash_index + 1:]

    if not is_valid_hostname(hostname):
        return False

    if resource is not None:
        if not is_valid_word(resource):
            return False

    return True

def main():
    s = sys.stdin.readline().rstrip('\n\r')
    if is_valid_jabber_id(s):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
